<?php
namespace App\Models;
use App\Enums\PaymentMode; use App\Enums\PaymentRecordStatus; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['payment_code','invoice_id','customer_id','payment_date','amount','payment_mode','transaction_reference','bank_reference','upi_reference','cheque_number','cheque_date','received_by','status','notes','created_by','updated_by'])]
class Payment extends Model { public function invoice():BelongsTo{return $this->belongsTo(Invoice::class);} public function customer():BelongsTo{return $this->belongsTo(Customer::class);} public function receiver():BelongsTo{return $this->belongsTo(User::class,'received_by');} public function receipt():HasOne{return $this->hasOne(PaymentReceipt::class);} public function statusHistory():HasMany{return $this->hasMany(PaymentStatusHistory::class);} protected function casts():array{return ['payment_date'=>'date','cheque_date'=>'date','amount'=>'decimal:2','payment_mode'=>PaymentMode::class,'status'=>PaymentRecordStatus::class];} }
